import{_ as a,o as l,c as n,a2 as i}from"./chunks/framework.1lR7qgqY.js";const p=JSON.parse('{"title":"M9 流程自動化","description":"","frontmatter":{},"headers":[],"relativePath":"build/m9-automation.md","filePath":"build/m9-automation.md","lastUpdated":null}'),e={name:"build/m9-automation.md"};function r(o,t,d,s,h,u){return l(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="m9-流程自動化" tabindex="-1">M9 流程自動化 <a class="header-anchor" href="#m9-流程自動化" aria-label="Permalink to &quot;M9 流程自動化&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ○ 依情境</li><li>狀態: 可閱讀 (M9.2 至 M9.4 僅有大綱)</li><li>資料基準日: 2026-10-26</li><li>待查證: KEV 清單取自彙整站, 應改連 CISA 原始來源</li></ul></div><p><strong>結論</strong>: 規則固定的工作 (排程彙整, 告警轉 ticket) 交給 n8n 這類流程自動化平台, 不需要模型自己判斷. 這類平台設計上會執行使用者提供的程式碼, 又保存憑證, 是 2026 年漏洞最集中的元件之一. 因此 n8n 放在獨立 VM, 只經模型閘道與工具閘道對外, 本身不保存外部系統的金鑰.</p><p><strong>這一塊在圖上的位置</strong>: VM 自動化區的 n8n. <strong>前置模組</strong>: M5, M7. <strong>完成後的狀態</strong>: 固定流程能自動執行, 也能以工具形式讓介面與代理呼叫.</p><h2 id="m9-1-低程式碼平台的風險" tabindex="-1">M9.1 低程式碼平台的風險 <a class="header-anchor" href="#m9-1-低程式碼平台的風險" aria-label="Permalink to &quot;M9.1 低程式碼平台的風險&quot;">​</a></h2><p>Langflow, n8n, Flowise 這類平台設計上就會執行使用者提供的程式碼, 預設以高權限執行, 又保存所有憑證, 因此 2026 年已有實際利用紀錄的漏洞最多.</p><table tabindex="0"><thead><tr><th>平台</th><th>授權</th><th>2026 年重大紀錄 (來源)</th></tr></thead><tbody><tr><td>Langflow</td><td>MIT</td><td>CISA KEV 多筆 (如 CVE-2026-33017, Sysdig 觀測到公告後 20 小時內即出現利用行為); VulnCheck 統計 2026 年已有第 12 個出現利用紀錄的 Langflow CVE</td></tr><tr><td>n8n</td><td>Sustainable Use License, 官方文件明言非 OSI 開源</td><td>CVE-2025-68613 (CVSS 9.9) 於 2026-03-11 列入 KEV; CVE-2026-21858 (CVSS 10.0, 未驗證) 於 2026-01-09 列入 VulnCheck KEV</td></tr><tr><td>Flowise</td><td>Apache 2.0 (企業目錄另計, 未驗證)</td><td>CVE-2025-71333 未驗證路徑穿越寫檔導致 RCE, 官方容器以 root 執行 (VulnCheck, 2026-08)</td></tr><tr><td>Dify</td><td>Dify Open Source License (非 OSI)</td><td>2026 年多為中度漏洞, 未見利用紀錄 (guard0 TrustVector, 2026-07)</td></tr></tbody></table><p>KEV 清單取自彙整站, 資料頁應改連 CISA 原始來源.</p><p>對初階讀者的建議 (信心: 高):</p><ul><li>若要學習, 只在本機或內網使用.</li><li>不直接對網際網路開放.</li><li>自動更新至最新修補版.</li><li>不把正式環境金鑰放進去.</li><li>稱 Dify 為「原始碼公開」, 不稱「開源」.</li></ul><h2 id="m9-2-n8n-與-langgraph-的分工" tabindex="-1">M9.2 n8n 與 LangGraph 的分工 <a class="header-anchor" href="#m9-2-n8n-與-langgraph-的分工" aria-label="Permalink to &quot;M9.2 n8n 與 LangGraph 的分工&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>n8n: 人先畫好流程, 照固定路徑執行; LangGraph: 模型在執行中決定下一步</li><li>兩者經工具閘道互相呼叫, 稽核紀錄集中在同一處</li></ul><h2 id="m9-3-架設-n8n" tabindex="-1">M9.3 架設 n8n <a class="header-anchor" href="#m9-3-架設-n8n" aria-label="Permalink to &quot;M9.3 架設 n8n&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>部署在獨立 VM, 只接受內網與閘道區連線</li><li>以 MCP Client 節點經工具閘道呼叫工具; 以 MCP Server Trigger 節點把流程提供為工具</li><li>授權: 自架免費但限內部使用</li></ul><h2 id="m9-4-驗收測試" tabindex="-1">M9.4 驗收測試 <a class="header-anchor" href="#m9-4-驗收測試" aria-label="Permalink to &quot;M9.4 驗收測試&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>n8n 的 VM 無法直接連到外部系統, 只能經閘道</li><li>排程流程與 Webhook 流程各完成一次</li></ul>',19)])])}const m=a(e,[["render",r]]);export{p as __pageData,m as default};
